/**
 * Properties for a new tab to be passed into TabMail.openTab().
 *
 * @typedef NativeTabProperties
 * @property {string} url
 * @property {?string} initialBrowsingContextGroupId
 * @property {?string} linkHandler
 * @property {?nsIPrincipal} triggeringPrincipal
